async function charge(sub) {
  return retry(async () => {
    const res = await fetch(PAY_URL, {
      method: 'POST',
      headers: { 'Idempotency-Key': crypto.randomUUID() },
      body: JSON.stringify({ amount: sub.amount, card: sub.card }),
    });
    if (res.status >= 500) throw new Error('retry');
    return res.json();
  }, { retries: 3 });
}
